// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX4} from "../src/MultiplicatorX4.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    MultiplicatorX4 c;
    Recorder rec;

    function setUp() public {
        c = new MultiplicatorX4();
        rec = new Recorder();
    }

    function testFuzz_property(uint256 seed, uint256 amount) public {
        vm.assume(amount <= VALUE_CAP);
        // Admissible domain: contract holds a strictly positive pre-balance, owner sends a positive value it can afford.
        seed = bound(seed, 1, 1e30);
        amount = bound(amount, 1, 1e30);

        address owner = address(this); // Owner is set at construction to the deployer (setUp caller)

        vm.deal(address(c), seed);   // give c a pre-existing balance
        vm.deal(owner, amount);      // owner can pay exactly the fuzzed value

        uint256 preBalance = address(c).balance;

        vm.prank(owner);
        c.Command{value: amount}(address(rec), "");

        // Reference forwards exactly msg.value out, so c's balance is unchanged; the mutant drains it to 0.
        assertTrue(address(c).balance == preBalance);
    }
}

contract Recorder {
    uint256 public received;
    receive() external payable {
        received += msg.value;
    }
}
